import java.util.ArrayList;
import java.util.Scanner;

public class TextDoc {

    public static void main(String[] args) {
        Scanner inputScanner = new Scanner(System.in);
        int linesCount = inputScanner.nextInt();
        inputScanner.nextLine();
        String fullLine = inputScanner.nextLine();
        String[] splitParts = fullLine.split("\\(.*?\\)");
        int maxLengthFound = 0;
        for (String part : splitParts) {
            String[] tokens = part.split("_");
            for (String token : tokens) {
                maxLengthFound = Math.max(token.length(), maxLengthFound);
            }
        }
        ArrayList<String> insideParentheses = new ArrayList<>();
        int startIdx = -1;
        for (int i = 0; i < fullLine.length(); i++) {
            if (fullLine.charAt(i) == '(') {
                startIdx = i;
            } else if (fullLine.charAt(i) == ')' && startIdx != -1) {
                insideParentheses.add(fullLine.substring(startIdx + 1, i));
            }
        }
        int totalWordsCount = 0;
        for (String segment : insideParentheses) {
            String[] wordsArray = segment.split("_");
            for (String word : wordsArray) {
                if (word.length() > 0) {
                    totalWordsCount++;
                }
            }
        }
        System.out.println(maxLengthFound + " " + totalWordsCount);
    }
}
